package com.enterprise.siem.incident;
import com.enterprise.siem.model.*; import com.enterprise.siem.database.*; import com.enterprise.siem.soar.ResponseAction; import com.enterprise.siem.soar.ResponseManager; import com.enterprise.siem.util.SIEMMetrics; import java.sql.SQLException; import java.time.Duration; import java.time.Instant; import java.util.Iterator; import java.util.LinkedHashMap; import java.util.Map;
public final class IncidentManager { private static final int MAX_INCIDENT_KEYS=100_000; private static final Duration INCIDENT_TTL=Duration.ofHours(1); private record Entry(Incident incident,Instant lastAccess){} private final IncidentRepository repository; private final ResponseManager response; private final SIEMMetrics metrics; private final Map<String,Entry> open=new LinkedHashMap<>(128,0.75f,true); public IncidentManager(IncidentRepository r,ResponseManager rm,SIEMMetrics m){repository=r;response=rm;metrics=m;}
 public synchronized void accept(Alert a){Instant now=Instant.now();cleanup(now);String key=a.ruleId()+":"+a.sourceIp();Entry current=open.get(key);boolean created=current==null||Duration.between(current.incident().createdAt(),a.timestamp()).abs().toSeconds()>=300;Incident i=created?new Incident(null,a.timestamp(),a.severity(),a.ruleId()+" incident","Correlated alert: "+a.description(),IncidentStatus.OPEN.name(),actionFor(a.severity())):current.incident();open.put(key,new Entry(i,now));if(open.size()>MAX_INCIDENT_KEYS){open.entrySet().iterator().remove();metrics.evictedKeys.increment();}try {repository.save(i); repository.linkAlert(i,a); if(created){metrics.incidentsGenerated.increment();response.respond(i,a);} }catch(SQLException e){metrics.databaseErrors.increment();}}
 public synchronized Incident transition(java.util.UUID incidentId, IncidentStatus status) throws SQLException { Incident current = repository.find(incidentId).orElseThrow(() -> new IllegalArgumentException("Unknown incident: " + incidentId)); Incident updated = current.withStatus(status); repository.save(updated); open.replaceAll((key, entry) -> entry.incident().incidentId().equals(incidentId) ? new Entry(updated, Instant.now()) : entry); return updated; }
 private static String actionFor(Severity severity){return severity==Severity.CRITICAL?ResponseAction.SIMULATE_ISOLATION.name():ResponseAction.LOG_INCIDENT.name();}
 private void cleanup(Instant now){Iterator<Map.Entry<String,Entry>> iterator=open.entrySet().iterator();while(iterator.hasNext())if(Duration.between(iterator.next().getValue().lastAccess(),now).compareTo(INCIDENT_TTL)>0){iterator.remove();metrics.evictedKeys.increment();}}
}
